<?php /** @var array{version:int,rules:array<string,mixed>,source:string} $current */ /** @var list<array<string,mixed>> $history */ /** @var bool $canManage */ $r = $current['rules']; $v = static fn (string $k, mixed $d): string => old($k, (string) $d); $chk = static fn (string $k): string => (old($k, $r[$k] ? '1' : '0') === '1') ? ' checked' : ''; ?>
<div class="page-head"><div><p class="eyebrow">Referral partners</p><h1>Commission rules</h1></div><a class="btn btn-ghost" href="/commissions">&larr; Ledger</a></div>
<div class="panel"><p>In force: <strong><?= $current['version'] > 0 ? 'version ' . (int) $current['version'] : 'shipped defaults (never edited)' ?></strong>. A change creates a new version. Entries already calculated keep the rules they were calculated under.</p>
    <p class="muted">The agreed structure is 10% after the verified qualifying advance and 5% after full payment. Rates are in basis points (1000 = 10%, 500 = 5%).</p>
<?php if ($canManage) : ?>
    <form method="post" action="/commissions/rules" class="form-grid" data-confirm="Save new commission rules?"><?= csrf_field() ?>
        <div class="field"><label for="a">Advance milestone rate (bps)</label><input id="a" name="advance_rate_bps" required inputmode="numeric" value="<?= e($v('advance_rate_bps', $r['advance_rate_bps'])) ?>"></div>
        <div class="field"><label for="f">Full-payment milestone rate (bps)</label><input id="f" name="full_rate_bps" required inputmode="numeric" value="<?= e($v('full_rate_bps', $r['full_rate_bps'])) ?>"></div>
        <div class="field"><label for="fm">Formula mode</label><select id="fm" name="formula_mode"><?php foreach (['cumulative' => 'Cumulative: total earned = 15% of eligible received payments', 'per_milestone' => 'Per milestone: 10% of the advance-stage payments + 5% of later payments'] as $c => $l) : ?><option value="<?= e($c) ?>"<?= $v('formula_mode', $r['formula_mode']) === $c ? ' selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select></div>
        <div class="field"><label for="am">Minimum advance (bps of contract value, 0 = any verified advance)</label><input id="am" name="advance_min_bps" inputmode="numeric" value="<?= e($v('advance_min_bps', $r['advance_min_bps'])) ?>"></div>
        <div class="field"><label for="ft">Full-payment tolerance (₹)</label><input id="ft" name="full_payment_tolerance_minor" inputmode="decimal" value="<?= e($v('full_payment_tolerance_minor', number_format((int) $r['full_payment_tolerance_minor'] / 100, 2, '.', ''))) ?>"></div>
        <div class="field"><label for="aw">Cancelled project: advance milestone</label><select id="aw" name="advance_without_completion"><?php foreach (['keep' => 'Stays earned', 'reverse' => 'Is reversed'] as $c => $l) : ?><option value="<?= e($c) ?>"<?= $v('advance_without_completion', $r['advance_without_completion']) === $c ? ' selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select></div>
        <div class="field"><label for="hd">Days between approval and Payable</label><input id="hd" name="payable_hold_days" inputmode="numeric" value="<?= e($v('payable_hold_days', $r['payable_hold_days'])) ?>"></div>
        <div class="field"><label for="mp">Minimum payout request (₹)</label><input id="mp" name="min_payout_minor" inputmode="decimal" value="<?= e($v('min_payout_minor', number_format((int) $r['min_payout_minor'] / 100, 2, '.', ''))) ?>"></div>
        <div class="field"><label class="check"><input type="checkbox" name="exclude_tax" value="1"<?= $chk('exclude_tax') ?>> Exclude tax collected from the base</label></div>
        <div class="field"><label class="check"><input type="checkbox" name="net_of_refunds" value="1"<?= $chk('net_of_refunds') ?>> Subtract refunds and chargebacks</label></div>
        <div class="field"><label class="check"><input type="checkbox" name="include_change_requests" value="1"<?= $chk('include_change_requests') ?>> Approved change requests raise the contract value that must be paid</label></div>
        <div class="field"><label class="check"><input type="checkbox" name="separation_of_duties" value="1"<?= $chk('separation_of_duties') ?>> Separation of duties: the person who approves a payout cannot record its payment</label></div>
        <div class="field"><label for="rn">Reason for the change (required)</label><input id="rn" name="reason" required maxlength="255" value="<?= e(old('reason')) ?>"></div>
        <div class="field"><label for="pw">Your password</label><input id="pw" name="confirm_password" type="password" required autocomplete="current-password"></div>
        <div class="form-actions"><button class="btn btn-primary" type="submit">Save as a new version</button></div></form>
<?php else : ?><dl class="detail-list"><?php foreach ($r as $k => $val) : ?><dt><?= e(str_replace('_', ' ', (string) $k)) ?></dt><dd><?= e(is_bool($val) ? ($val ? 'yes' : 'no') : (string) $val) ?></dd><?php endforeach; ?></dl><?php endif; ?></div>
<div class="panel"><h2>Version history</h2><ol class="timeline"><?php foreach ($history as $h) : ?><li><strong>Version <?= (int) $h['version'] ?></strong> <span class="muted"><?= e(local_time($h['created_at'])) ?> · <?= e($h['author'] ?? 'system') ?></span><p><?= e($h['reason'] ?? '') ?></p></li><?php endforeach; ?><?php if ($history === []) : ?><li class="muted">No versions saved yet: the shipped defaults apply.</li><?php endif; ?></ol></div>
